package config

import (
	"os"
	"strings"
	"testing"
)

// minEnv sets the four required env vars that all Load() calls need, plus
// ENV=test — the allowlisted non-production value that lets the dev-mode
// escape hatch tests in this file enable dev mode without also asserting
// the production guard. Tests that specifically exercise the ENV allowlist
// (TestLoad_*DevMode_FatalInProduction and TestLoad_DevModeAllowedEnv)
// override ENV after calling minEnv.
func minEnv(t *testing.T) {
	t.Helper()
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
	t.Setenv("OTLP_ENDPOINT", "otel-collector:4317")
	t.Setenv("ENV", "test")
}

// unsetEnvForTest removes key from the process environment for the duration
// of the test, restoring whatever value (or absence) preceded it. t.Setenv
// can only pin a value, not genuinely unset a var, so this is needed for the
// "ENV was never configured" case the allowlist must refuse.
func unsetEnvForTest(t *testing.T, key string) {
	t.Helper()
	prev, existed := os.LookupEnv(key)
	if err := os.Unsetenv(key); err != nil {
		t.Fatalf("os.Unsetenv(%q): %v", key, err)
	}
	t.Cleanup(func() {
		if existed {
			_ = os.Setenv(key, prev)
		} else {
			_ = os.Unsetenv(key)
		}
	})
}

func TestLoad_Minimum(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
	t.Setenv("OTLP_ENDPOINT", "otel-collector:4317")
	// Vault token required when not in dev mode.
	t.Setenv("VAULT_TOKEN", "s.test-token")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.ServiceName != "dialogue-bff" {
		t.Errorf("default ServiceName = %q, want dialogue-bff", cfg.ServiceName)
	}
	if cfg.HTTPAddr != ":8080" {
		t.Errorf("default HTTPAddr = %q, want :8080", cfg.HTTPAddr)
	}
	if cfg.OTLPInsecure {
		t.Errorf("default OTLPInsecure = true, want false")
	}
	if cfg.OIDCAudience != "dialogue-bff" {
		t.Errorf("OIDCAudience = %q, want dialogue-bff", cfg.OIDCAudience)
	}
	if cfg.DialogueSvcAddr != "dialogue-svc:50051" {
		t.Errorf("DialogueSvcAddr = %q", cfg.DialogueSvcAddr)
	}
	// OrgSvcAddr is OPTIONAL — unset here, so it defaults to empty and
	// Load must still succeed (curation routes fail closed without it).
	if cfg.OrgSvcAddr != "" {
		t.Errorf("OrgSvcAddr = %q, want empty when ORG_SVC_ADDR unset", cfg.OrgSvcAddr)
	}
}

func TestLoad_OrgSvcAddr(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
	t.Setenv("OTLP_ENDPOINT", "otel-collector:4317")
	t.Setenv("VAULT_TOKEN", "s.test-token")
	t.Setenv("ORG_SVC_ADDR", "org-svc:50051")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.OrgSvcAddr != "org-svc:50051" {
		t.Errorf("OrgSvcAddr = %q, want org-svc:50051", cfg.OrgSvcAddr)
	}
}

func TestLoad_MissingRequired(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "")
	t.Setenv("OIDC_AUDIENCE", "x")
	t.Setenv("DIALOGUE_SVC_ADDR", "x")
	t.Setenv("OTLP_ENDPOINT", "x")
	if _, err := Load(); err == nil {
		t.Fatal("Load with empty OIDC_ISSUER_URL: want error, got nil")
	}
}

func TestLoad_MTLSPartial(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "x")
	t.Setenv("OIDC_AUDIENCE", "x")
	t.Setenv("DIALOGUE_SVC_ADDR", "x")
	t.Setenv("OTLP_ENDPOINT", "x")
	t.Setenv("MTLS_CERT_FILE", "/cert")
	t.Setenv("MTLS_KEY_FILE", "")
	t.Setenv("MTLS_CA_FILE", "")
	if _, err := Load(); err == nil {
		t.Fatal("Load with partial mTLS env: want error, got nil")
	}
}

func TestLoad_BoolEnv(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "x")
	t.Setenv("OIDC_AUDIENCE", "x")
	t.Setenv("DIALOGUE_SVC_ADDR", "x")
	t.Setenv("OTLP_ENDPOINT", "x")
	t.Setenv("OTLP_INSECURE", "true")
	// Vault token required when not in dev mode.
	t.Setenv("VAULT_TOKEN", "s.test-token")
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if !cfg.OTLPInsecure {
		t.Error("OTLP_INSECURE=true → OTLPInsecure should be true")
	}
}

// ---------------------------------------------------------------------------
// Vault + Telegram fields — TDD additions (sub-PR 8 Task A-3)
// ---------------------------------------------------------------------------

// TestLoad_VaultDefaults asserts defaults applied when no vault env is set.
// Both dev modes are true here so VaultToken is not required.
func TestLoad_VaultDefaults(t *testing.T) {
	minEnv(t)
	t.Setenv("DIALOGUE_TELEGRAM_DEV_MODE", "true")
	t.Setenv("DIALOGUE_WHATSAPP_DEV_MODE", "true")
	t.Setenv("DIALOGUE_FACEBOOK_DEV_MODE", "true")
	t.Setenv("DIALOGUE_INSTAGRAM_DEV_MODE", "true") // Task 13: included in the Vault OR-chain
	t.Setenv("DIALOGUE_ANDROID_SMS_DEV_MODE", "true")
	// Ensure vault vars are absent from env.
	t.Setenv("VAULT_ADDR", "")
	t.Setenv("VAULT_TOKEN", "")
	t.Setenv("DIALOGUE_VAULT_MOUNT", "")
	t.Setenv("DIALOGUE_TELEGRAM_OLD_SECRET_GRACE_S", "")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.VaultAddr != "http://vault:8200" {
		t.Errorf("VaultAddr default = %q, want http://vault:8200", cfg.VaultAddr)
	}
	if cfg.VaultToken != "" {
		t.Errorf("VaultToken default = %q, want empty string", cfg.VaultToken)
	}
	if cfg.VaultMount != "dialogue" {
		t.Errorf("VaultMount default = %q, want dialogue", cfg.VaultMount)
	}
	if cfg.TelegramOldSecretGraceS != 60 {
