package config

import "strings"

// ServiceAccountTokenURL builds the OIDC token endpoint dialogue-bff uses to
// mint its Android SMS service-account (client_credentials) token.
//
// WHY: dialogue-bff mints this token from INSIDE the container, where the
// public issuer URL (e.g. http://localhost:8080/...) is unreachable. When an
// in-network OIDCInternalURL (e.g. http://keycloak:8080/...) is set we prefer
// it so the mint actually completes. Keycloak's fixed frontend hostname
// (KC_HOSTNAME=localhost) means the minted token still carries iss=<public
// issuer>, so dialogue-svc's verifier accepts it regardless of which host was
// reached.
//
// Mirrors services/range-bff/internal/config/token_url.go exactly.
func ServiceAccountTokenURL(issuerURL, internalURL string) string {
	base := internalURL
	if base == "" {
		base = issuerURL
	}
	return strings.TrimRight(base, "/") + "/protocol/openid-connect/token"
}



