package config

import (
	"os"
	"strings"
	"testing"
)

// minEnv sets the four required env vars that all Load() calls need, plus
// ENV=test — the allowlisted non-production value that lets the dev-mode
// escape hatch tests in this file enable dev mode without also asserting
// the production guard. Tests that specifically exercise the ENV allowlist
// (TestLoad_*DevMode_FatalInProduction and TestLoad_DevModeAllowedEnv)
// override ENV after calling minEnv.
func minEnv(t *testing.T) {
	t.Helper()
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
	t.Setenv("OTLP_ENDPOINT", "otel-collector:4317")
	t.Setenv("ENV", "test")
}

// unsetEnvForTest removes key from the process environment for the duration
// of the test, restoring whatever value (or absence) preceded it. t.Setenv
// can only pin a value, not genuinely unset a var, so this is needed for the
// "ENV was never configured" case the allowlist must refuse.
func unsetEnvForTest(t *testing.T, key string) {
	t.Helper()
	prev, existed := os.LookupEnv(key)
	if err := os.Unsetenv(key); err != nil {
		t.Fatalf("os.Unsetenv(%q): %v", key, err)
	}
	t.Cleanup(func() {
		if existed {
			_ = os.Setenv(key, prev)
		} else {
			_ = os.Unsetenv(key)
		}
	})
}

func TestLoad_Minimum(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
	t.Setenv("OTLP_ENDPOINT", "otel-collector:4317")
	// Vault token required when not in dev mode.
	t.Setenv("VAULT_TOKEN", "s.test-token")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.ServiceName != "dialogue-bff" {
		t.Errorf("default ServiceName = %q, want dialogue-bff", cfg.ServiceName)
	}
	if cfg.HTTPAddr != ":8080" {
		t.Errorf("default HTTPAddr = %q, want :8080", cfg.HTTPAddr)
	}
	if cfg.OTLPInsecure {
		t.Errorf("default OTLPInsecure = true, want false")
	}
	if cfg.OIDCAudience != "dialogue-bff" {
		t.Errorf("OIDCAudience = %q, want dialogue-bff", cfg.OIDCAudience)
	}
	if cfg.DialogueSvcAddr != "dialogue-svc:50051" {
		t.Errorf("DialogueSvcAddr = %q", cfg.DialogueSvcAddr)
	}
	// OrgSvcAddr is OPTIONAL — unset here, so it defaults to empty and
	// Load must still succeed (curation routes fail closed without it).
	if cfg.OrgSvcAddr != "" {
		t.Errorf("OrgSvcAddr = %q, want empty when ORG_SVC_ADDR unset", cfg.OrgSvcAddr)
	}
}

func TestLoad_OrgSvcAddr(t *testing.T) {
	t.Setenv("OIDC_ISSUER_URL", "http://kc/realms/omnicore")
	t.Setenv("OIDC_AUDIENCE", "dialogue-bff")
	t.Setenv("DIALOGUE_SVC_ADDR", "dialogue-svc:50051")
