// ---------------------------------------------------------------------------
// ENV allowlist — the webhook dev-mode escape hatch must fail closed for
// every ENV value except an explicit, known non-production allowlist. A
// denylist on the single string "production" let ENV=prod, ENV=staging, and
// an unset/unconfigured ENV all through — this table pins the fix.
// ---------------------------------------------------------------------------

// TestLoad_TelegramDevMode_EnvAllowlist asserts DIALOGUE_TELEGRAM_DEV_MODE=true
// is permitted only for the exact allowlisted ENV values (case/whitespace
// insensitive) and refused for everything else, including unset, empty,
// "prod", "staging", and an arbitrary unrecognized string.
func TestLoad_TelegramDevMode_EnvAllowlist(t *testing.T) {
	tests := []struct {
		name      string
		envValue  string
		unsetEnv  bool // when true, ENV is never set at all (not even "")
		wantAllow bool
	}{
		{name: "dev", envValue: "dev", wantAllow: true},
		{name: "development", envValue: "development", wantAllow: true},
		{name: "test", envValue: "test", wantAllow: true},
		{name: "local", envValue: "local", wantAllow: true},
		{name: "uppercase DEV allowed case-insensitively", envValue: "DEV", wantAllow: true},
		{name: "whitespace-padded dev allowed after trim", envValue: "  dev  ", wantAllow: true},
		{name: "production refused", envValue: "production", wantAllow: false},
		{name: "prod refused", envValue: "prod", wantAllow: false},
		{name: "staging refused", envValue: "staging", wantAllow: false},
		{name: "empty string refused", envValue: "", wantAllow: false},
		{name: "unset refused", unsetEnv: true, wantAllow: false},
		{name: "arbitrary unrecognized string refused", envValue: "qa-sandbox-42", wantAllow: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			minEnv(t)
			t.Setenv("VAULT_TOKEN", "s.tok") // provide token so only the dev-mode guard fires
			t.Setenv("DIALOGUE_TELEGRAM_DEV_MODE", "true")
			if tt.unsetEnv {
				unsetEnvForTest(t, "ENV")
			} else {
				t.Setenv("ENV", tt.envValue)
			}

			cfg, err := Load()
			if tt.wantAllow {
				if err != nil {
					t.Fatalf("ENV=%q: expected Load to succeed, got: %v", tt.envValue, err)
				}
				if !cfg.TelegramDevMode {
					t.Errorf("ENV=%q: expected TelegramDevMode=true", tt.envValue)
				}
			} else {
				if err == nil {
					t.Fatalf("ENV=%q: expected Load to refuse dev mode, got success", tt.envValue)
				}
				if !strings.Contains(err.Error(), "DIALOGUE_TELEGRAM_DEV_MODE=true is not permitted") {
					t.Errorf("ENV=%q: error = %q; want it to mention dev mode not permitted", tt.envValue, err.Error())
				}
			}
		})
	}
}

// TestLoad_AllDevModes_EnvAllowlist_UnsetRefusesEachIndependently asserts the
