func TestLoad_AllDevModes_EnvAllowlist_UnsetRefusesEachIndependently(t *testing.T) {
	flags := []string{
		"DIALOGUE_TELEGRAM_DEV_MODE",
		"DIALOGUE_WHATSAPP_DEV_MODE",
		"DIALOGUE_FACEBOOK_DEV_MODE",
		"DIALOGUE_INSTAGRAM_DEV_MODE",
		"DIALOGUE_ANDROID_SMS_DEV_MODE",
	}

	for _, flag := range flags {
		t.Run(flag, func(t *testing.T) {
			minEnv(t)
			t.Setenv("VAULT_TOKEN", "s.tok")
			t.Setenv(flag, "true")
